import random


def generate(seed: int = 0) -> list[str]:
    """Flattened values are sorted descending and placed row-major, so rows and columns are non-increasing."""
    r = random.Random(seed)
    cases = []
    seen = set()
    while len(cases) < 600:
        m = r.randint(1, 12)
        n = r.randint(1, 12)
        vals = sorted([r.randint(-100, 100) for _ in range(m * n)], reverse=True)
        grid = [vals[i * n : (i + 1) * n] for i in range(m)]
        # Row-major descending order also guarantees columns are non-increasing.
        key = tuple(map(tuple, grid))
        if key not in seen:
            seen.add(key)
            cases.append(grid)
    return [f"candidate(grid={x!r})" for x in cases]


